 if(s.phase==='formalised')return `${tr('Mean','Min')} = ${decimal(s.total)} ÷ ${s.count} = <svg viewBox="0 0 120 50" aria-label="${decimal(mean(data()))}">${fractionText(mean(data()),55,29,29)}</svg>`;
