 $('stApplyChange').onclick=()=>{pause();try{if(!$('stOperand').value.trim())throw Error('Missing value');workspace.modifyData($('stOperation').value,Number($('stOperand').value));selected=null;$('stMeanError').textContent='';sync();}catch{$('stMeanError').textContent=tr('Keep every result between 0 and 100, with at most 2 decimal places.','Pastikan setiap hasil antara 0 hingga 100, maksimum 2 tempat perpuluhan.');}};
 $('stCompare').onclick=()=>{pause();comparisonUndo=workspace;comparison={sets:[workspace,new StatisticsWorkspace(simpleQuestion(++seed))],active:1};workspace=comparison.sets[1];question=workspace.question;view='current';selected=null;$('stAdjustPanel').hidden=true;sync();};
 $('stSetA').onclick=()=>activateDataset(0);$('stSetB').onclick=()=>activateDataset(1);
 $('stCurrentPanel').onclick=e=>{if(comparison&&!e.target.closest('[data-piece]'))activateDataset(0);};$('stOriginalPanel').onclick=e=>{if(comparison&&!e.target.closest('[data-piece]'))activateDataset(1);};
