 function editKey(key){if(key==='C')custom='';else if(key==='Backspace'||key==='⌫'||key==='Delete')custom=custom.slice(0,-1);else if(/^[0-9., \-]$/.test(key)&&custom.length<180)custom+=key;$('stDataInput').value=custom;}
 host.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>editKey(b.dataset.key));$('stDataInput').onkeydown=e=>{if(/^[0-9., \-]$/.test(e.key)||['Backspace','Delete','Enter'].includes(e.key)){e.preventDefault();e.stopPropagation();if(e.key==='Enter')useCustom();else editKey(e.key);}};
 function useCustom(){try{const values=parseData(custom);load({id:'custom-'+Date.now(),source:'custom',title:{en:'Custom data',bm:'Data sendiri'},data:values,tags:['custom'],startRepresentation:'raw-data',generatorProfile:profile(values)});}catch(error){$('stDataError').textContent=error.message==='length'?tr('Use 2–24 observations.','Gunakan 2–24 cerapan.'):error.message==='range'?tr('Use values from 0 to 100 with at most 2 decimal places.','Gunakan nilai 0 hingga 100, maksimum 2 tempat perpuluhan.'):tr('Separate valid values with commas or spaces. No empty entries.','Pisahkan nilai sah dengan koma atau ruang. Tiada entri kosong.');}}
 $('stUseCustom').onclick=useCustom;
 function keydown(e){if(e.target.closest('input,textarea,select,button,[role=button]')||!$('stDataPanel').hidden)return;if(e.key==='Enter'){e.preventDefault();pause();step();}else if(e.key===' '){e.preventDefault();togglePlay();}else if(e.key.toLowerCase()==='r'){e.preventDefault();change(()=>workspace.reset());}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(['median','quartiles'].includes(workspace.concept)){e.preventDefault();change(()=>workspace.moveLocator(e.key==='ArrowLeft'?-1:1));}}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();change(undo);}else if(e.key==='Escape'&&presentation){e.preventDefault();$('stPresentation').click();}}
 host.addEventListener('keydown',keydown);const resize=new ResizeObserver(schedule);resize.observe($('stStages'));sync();
 return()=>{disposed=true;pause();cancelAnimationFrame(renderFrame);resize.disconnect();sideMedia.removeEventListener('change',responsiveLayout);host.removeEventListener('keydown',keydown);currentScene.dispose();originalScene.dispose();host.classList.remove('statistics-mode','st-presenting');};
